def make(alpha, beta):
    class S(fdem.sources.MagDipole):
        def s_m(self, simulation):
            b_p = self.bPrimary(simulation)
            if simulation._formulation == "HJ":
                if beta == 0.0:
                    return Zero()
                return 1j * omega(self.frequency) * beta * (simulation.MeMu * (b_p / self.mu))
            return -1j * omega(self.frequency) * b_p

        def s_e(self, simulation):
            if simulation._formulation == "HJ":
                if alpha == 0.0:
                    return Zero()
                C = simulation.mesh.edge_curl
                return alpha * (C * (self.bPrimary(simulation) / self.mu))
            return super().s_e(simulation)

    S.__name__ = f"a{alpha}_b{beta}"
    return S


def analytic_h_z(locs, m=1.0, o="z"):
    ovec = {"x": np.array([1., 0, 0]), "y": np.array([0, 1., 0]), "z": np.array([0, 0, 1.])}[o]
    R = locs
    r = np.linalg.norm(R, axis=1)
    Rh = R / r[:, None]
    mv = m * ovec
