"""Well-conditioned inductive benchmark: HJ source parameterizations vs geoana wholespace."""
import sys, time
import numpy as np
from scipy.constants import mu_0
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent / "source"))

from discretize import TensorMesh
from simpeg import maps
import simpeg.electromagnetics.frequency_domain as fdem
from simpeg.utils import Zero
from simpeg.electromagnetics.utils import omega
from geoana.em.fdem import MagneticDipoleWholeSpace as FDws


def make(sm_terms, se_terms):
    class S(fdem.sources.MagDipole):
        def s_m(self, simulation):
            if simulation._formulation != "HJ":
                return super().s_m(simulation)
            if sm_terms is None:
                return Zero()
            b_p = self.bPrimary(simulation)
            w = omega(self.frequency)
            kind, sign = sm_terms
            if kind == "Me":
                base = simulation.Me * b_p
            elif kind == "bare":
                base = b_p
            elif kind == "MeMu":
                base = simulation.MeMu * (b_p / self.mu)
            return sign * 1j * w * base

        def s_e(self, simulation):
            if simulation._formulation != "HJ":
                return super().s_e(simulation)
            if se_terms is None:
                return Zero()
            kind, sign = se_terms
            b_p = self.bPrimary(simulation)
            if kind == "Chp":
                C = simulation.mesh.edge_curl
                return sign * (C * (b_p / self.mu))
            elif kind == "contrast":
                mu_s = simulation.mu - self.mu
                MM = simulation.mesh.get_edge_inner_product(mu_s, invert_matrix=True)
                return -simulation.mesh.edge_curl * (MM * b_p)

    S.__name__ = f"S{sm_terms}{se_terms}"
    return S


def mesh(cell, core, padding, factor=1.3):
    widths = [(cell, padding, -factor), (cell, core), (cell, padding, factor)]
    return TensorMesh([widths, widths, widths], origin="CCC")


m = mesh(2.5, 16, 3)
sigma, freq = 0.1, 300.0
model = np.full(m.n_cells, sigma)
locs = np.array([
    [15.0, 0.0, 0.0],
    [20.0, 0.0, 0.0],
    [0.0, 0.0, 15.0],
    [0.0, 0.0, 20.0],
    [17.5, 7.5, 0.0],
])
ana = FDws(frequency=freq, sigma=sigma, mu=mu_0, location=np.zeros(3), orientation="z", moment=1.0)
an = ana.magnetic_field(locs)[:, 2].real
print("geoana:", list(np.round(an, 10)), flush=True)

def run(srccls, cls):
    rx = fdem.receivers.PointMagneticField(locs, orientation="z", component="real")
    src = srccls([rx], location=np.zeros(3), frequency=freq, moment=1.0, orientation="z", mu=mu_0)
    sim = cls(m, survey=fdem.Survey([src]), sigmaMap=maps.IdentityMap())
    return np.asarray(sim.dpred(model)).reshape(-1)

